sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var detail = String(event.parm2 || '').split('||');
    var body = detail[0] || '';
    var status = detail[1] || '';
    var timeOfFailure = new GlideDateTime().getDisplayValue();
    template.print('<div style="font-size:16px;">');
    template.print('<div style="font-size:20px;line-height:30px;font-weight:600;padding-top:32px;">Communication failure between HP Workforce Experience and ServiceNow is detected</div>');
    template.print('<div style="padding-top:16px;padding-bottom:32px;">');
    template.print('Time of Failure: <span style="font-weight:600;">' + timeOfFailure + '</span><br/>');
    template.print('Nature of the Issue: <span style="font-weight:600;">' + body + '</span><br/>');
    template.print('Status of the Issue: <span style="font-weight:600;">' + status + '</span><br/>');
    template.print('</div></div>');
})(current, template, email, email_action, event);
